import { type CnOptions, cn as mergeClasses } from "tailwind-variants";

export function cn(...classes: CnOptions): string {
  return mergeClasses(...classes) ?? "";
}

import type { ComponentProps, ReactNode } from "react";
import { cn } from "./utils";

export interface MessageProps extends ComponentProps<"article"> {
  sender: string;
  side?: "incoming" | "outgoing" | "system";
  avatar?: ReactNode;
  timestamp?: string;
  dateTime?: string;
  status?: string;
  actions?: ReactNode;
}

export function Message({
  sender,
  side = "incoming",
  avatar,
  timestamp,
  dateTime,
  status,
  actions,
  children,
  className,
  ...props
}: MessageProps) {
  return (
    <article
      {...props}
      data-slot="message"
      data-side={side}
      aria-label={props["aria-label"] ?? `${sender} message`}
      className={cn(
        "flex min-w-0 items-start gap-2.5",
        side === "outgoing" && "justify-end",
        side === "system" && "justify-center",
        className,
      )}
    >
      {side === "incoming" && avatar}
      <div
        className={cn(
          "min-w-0 max-w-[88%] sm:max-w-[75%]",
          side === "incoming" && avatar && "max-w-[calc(100%_-_3.25rem)]",
          side === "system" && "max-w-full text-center",
        )}
      >
        {side !== "system" && (
          <p
            data-slot="message-sender"
            className="mb-1 px-1 text-xs font-medium text-muted-foreground"
          >
            {sender}
          </p>
        )}
        <div
          data-slot="message-content"
          className={cn(
            "min-w-0 whitespace-pre-wrap [overflow-wrap:anywhere] rounded-2xl px-4 py-3 text-sm leading-6",
            side === "outgoing" &&
              "rounded-tr-md bg-accent text-accent-foreground",
            side === "incoming" &&
              "rounded-tl-md border border-border bg-card text-card-foreground shadow-[var(--shadow-card)]",
            side === "system" && "bg-muted/70 text-muted-foreground",
          )}
        >
          {children}
        </div>
        {(timestamp || status || actions) && (
          <div className="mt-1.5 flex flex-wrap items-center gap-x-2 gap-y-1 px-1 text-xs text-muted-foreground">
            {timestamp && (
              <time dateTime={dateTime} data-slot="message-time">
                {timestamp}
              </time>
            )}
            {status && <span data-slot="message-status">{status}</span>}
            {actions && (
              <div data-slot="message-actions" className="flex gap-1">
                {actions}
              </div>
            )}
          </div>
        )}
      </div>
    </article>
  );
}

"use client";

import { type HTMLAttributes, useState } from "react";
import { cn } from "./utils";

export interface AvatarProps extends HTMLAttributes<HTMLSpanElement> {
  name: string;
  src?: string;
  initials?: string;
}

export function Avatar({
  name,
  src,
  initials,
  className,
  ...props
}: AvatarProps) {
  const [failedSrc, setFailedSrc] = useState<string | undefined>();
  const showImage = Boolean(src && src !== failedSrc);
  const fallback =
    initials ??
    name
      .trim()
      .split(/\s+/)
      .slice(0, 2)
      .map((part) => part[0])
      .join("")
      .toLocaleUpperCase();

  return (
    <span
      {...props}
      role="img"
      aria-label={name}
      data-slot="avatar"
      className={cn(
        "inline-grid size-10 shrink-0 place-items-center overflow-hidden rounded-full bg-accent text-xs font-semibold text-accent-foreground ring-1 ring-border/70",
        className,
      )}
    >
      {showImage ? (
        // Portable copyable component; Next Image would require a Next.js dependency.
        // biome-ignore lint/performance/noImgElement: Keep the avatar usable outside Next.js.
        <img
          src={src}
          alt=""
          data-slot="avatar-image"
          className="size-full object-cover"
          onError={() => setFailedSrc(src)}
        />
      ) : (
        <span aria-hidden="true" data-slot="avatar-fallback">
          {fallback}
        </span>
      )}
    </span>
  );
}

export function AvatarGroup({
  className,
  ...props
}: HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      data-slot="avatar-group"
      className={cn(
        "flex items-center -space-x-2 rtl:space-x-reverse [&_[data-slot=avatar]]:ring-2 [&_[data-slot=avatar]]:ring-background",
        className,
      )}
      {...props}
    />
  );
}

import { tv, type VariantProps } from "tailwind-variants";

export const buttonStyles = tv({
  base: "inline-flex shrink-0 cursor-default items-center justify-center gap-2 whitespace-nowrap rounded-md font-medium tracking-[-0.01em] data-[disabled]:cursor-default data-[disabled]:opacity-50 data-[disabled]:shadow-none data-[focus-visible]:outline-2 data-[focus-visible]:outline-offset-3 data-[focus-visible]:outline-ring",
  variants: {
    variant: {
      default:
        "bg-primary text-primary-foreground shadow-[var(--shadow-card)] hover:bg-primary/90 data-[pressed]:bg-primary/90",
      secondary:
        "bg-secondary text-secondary-foreground hover:bg-border/70 data-[pressed]:bg-border/70",
      outline:
        "border border-border bg-card text-foreground shadow-[var(--shadow-card)] hover:bg-muted data-[pressed]:bg-muted",
      ghost: "text-foreground hover:bg-muted data-[pressed]:bg-muted",
      destructive:
        "bg-destructive text-background shadow-[var(--shadow-card)] hover:bg-destructive/90 data-[pressed]:bg-destructive/90",
      nav: "text-foreground hover:bg-muted aria-[pressed=true]:bg-accent aria-[pressed=true]:text-accent-foreground aria-[pressed=true]:hover:bg-accent",
    },
    size: {
      default: "h-11 px-5 text-sm",
      sm: "h-9 px-3.5 text-sm",
      lg: "h-12 px-6 text-sm",
      icon: "size-11 cursor-pointer p-0",
      nav: "h-9 w-full justify-center px-0 text-xs sm:justify-start sm:px-2.5",
    },
  },
  defaultVariants: { variant: "default", size: "default" },
});

export const buttonLinkStyles = tv({
  extend: buttonStyles,
  base: "cursor-pointer",
});

export type ButtonVariant = NonNullable<
  VariantProps<typeof buttonStyles>["variant"]
>;
export type ButtonSize = NonNullable<VariantProps<typeof buttonStyles>["size"]>;

"use client";

import { motion, useReducedMotion } from "motion/react";
import {
  Button as AriaButton,
  type ButtonProps as AriaButtonProps,
  composeRenderProps,
} from "react-aria-components";
import {
  type ButtonSize,
  type ButtonVariant,
  buttonStyles,
} from "./button-styles";

export interface ButtonProps
  extends Omit<
    AriaButtonProps,
    | "style"
    | "onAnimationStart"
    | "onAnimationEnd"
    | "onAnimationIteration"
    | "onHoverStart"
    | "onHoverEnd"
  > {
  ref?: React.Ref<HTMLButtonElement>;
  variant?: ButtonVariant;
  size?: ButtonSize;
  static?: boolean;
}

const MotionButton = motion.create(AriaButton);

export function Button({
  className,
  variant = "default",
  size = "default",
  static: isStatic = false,
  ...props
}: ButtonProps) {
  const reduceMotion = useReducedMotion();
  return (
    <MotionButton
      data-slot="button"
      data-variant={variant}
      data-size={size}
      whileTap={isStatic || reduceMotion ? undefined : { scale: 0.96 }}
      transition={{ type: "spring", duration: 0.3, bounce: 0 }}
      className={composeRenderProps(className, (className) =>
        buttonStyles({ variant, size, className }),
      )}
      {...props}
    />
  );
}

"use client";

import { useEffect, useState } from "react";
import { Check, Copy, Warning } from "reicon-react";
import { Button, type ButtonProps } from "./button";

export interface CopyButtonProps
  extends Omit<ButtonProps, "children" | "onPress" | "type"> {
  value: string;
  label?: string;
  text?: string;
}

export function CopyButton({
  value,
  label = "Copy",
  text = "Copy",
  variant = "outline",
  size = "default",
  ...props
}: CopyButtonProps) {
  const [state, setState] = useState<"idle" | "copied" | "failed">("idle");

  useEffect(() => {
    if (state === "idle") return;
    const timeout = window.setTimeout(() => setState("idle"), 2000);
    return () => window.clearTimeout(timeout);
  }, [state]);

  async function copy() {
    try {
      await navigator.clipboard.writeText(value);
      setState("copied");
    } catch {
      setState("failed");
    }
  }

  return (
    <>
      <Button
        {...props}
        type="button"
        data-slot="copy-button"
        variant={variant}
        size={size}
        aria-label={
          state === "copied"
            ? "Copied to clipboard"
            : state === "failed"
              ? "Copy failed. Try again"
              : label
        }
        onPress={() => void copy()}
      >
        {state === "copied" ? (
          <Check size={16} aria-hidden="true" />
        ) : state === "failed" ? (
          <Warning size={16} aria-hidden="true" />
        ) : (
          <Copy size={16} aria-hidden="true" />
        )}
        {state === "copied" ? "Copied" : state === "failed" ? "Retry" : text}
      </Button>
      <output className="sr-only" aria-live="polite">
        {state === "copied"
          ? "Copied to clipboard"
          : state === "failed"
            ? "Copy failed. Try again."
            : ""}
      </output>
    </>
  );
}

"use client";

import {
  AnimatePresence,
  motion,
  useIsPresent,
  useReducedMotion,
} from "motion/react";
import type { ComponentProps, ReactNode } from "react";
import { cn } from "./utils";

export interface PresenceListProps<T>
  extends Omit<ComponentProps<"ul">, "children"> {
  items: readonly T[];
  getKey: (item: T) => string | number;
  children: (item: T) => ReactNode;
}

function PresenceListRow({
  children,
  reducedMotion,
}: {
  children: ReactNode;
  reducedMotion: boolean;
}) {
  const isPresent = useIsPresent();
  return (
    <motion.li
      data-slot="presence-list-item"
      inert={!isPresent}
      aria-hidden={!isPresent || undefined}
      layout={reducedMotion ? false : "position"}
      initial={reducedMotion ? false : { opacity: 0, y: 6 }}
      animate={{ opacity: 1, y: 0 }}
      exit={reducedMotion ? { opacity: 1 } : { opacity: 0, y: -6 }}
      transition={{ duration: reducedMotion ? 0 : 0.2, ease: "easeOut" }}
    >
      {children}
    </motion.li>
  );
}

export function PresenceList<T>({
  items,
  getKey,
  children,
  className,
  ...props
}: PresenceListProps<T>) {
  const reducedMotion = useReducedMotion() === true;
  return (
    <ul
      {...props}
      data-slot="presence-list"
      className={cn("grid gap-2", className)}
    >
      <AnimatePresence initial={false}>
        {items.map((item) => (
          <PresenceListRow key={getKey(item)} reducedMotion={reducedMotion}>
            {children(item)}
          </PresenceListRow>
        ))}
      </AnimatePresence>
    </ul>
  );
}

